package io.github.knaitoe.theoldesthouse.gametest;

import io.github.knaitoe.theoldesthouse.TheOldestHouse;
import io.github.knaitoe.theoldesthouse.labyrinth.*;
import java.util.*;
import net.minecraft.advancements.AdvancementHolder;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.level.GameType;
import net.neoforged.neoforge.gametest.*;

/** 0.4.165: the House's two advancement tabs, generated by tools/generate_advancements.py and awarded by HouseAdvancements. */
@GameTestHolder(TheOldestHouse.MOD_ID)
@PrefixGameTestTemplate(false)
public final class AdvancementTests {
    private static AdvancementHolder get(GameTestHelper h,String tab,String id){return h.getLevel().getServer().getAdvancements().get(ResourceLocation.fromNamespaceAndPath(TheOldestHouse.MOD_ID,tab+"/"+id));}
    private static List<AdvancementHolder> tab(GameTestHelper h,String tab){
        var out=new ArrayList<AdvancementHolder>();
        for(var holder:h.getLevel().getServer().getAdvancements().getAllAdvancements())if(holder.id().getNamespace().equals(TheOldestHouse.MOD_ID)&&holder.id().getPath().startsWith(tab+"/"))out.add(holder);
        return out;
    }

    @GameTest(template="empty") public static void twoTabsEveryStoryUnderItsKindNothingAnnouncedNothingPaidEveryEndingHidden(GameTestHelper h){
        var house=tab(h,"house");var account=tab(h,"account");
        h.assertTrue(house.size()==25,"the journey tab has its 25 advancements: "+house.size());
        h.assertTrue(account.size()==7+5+WitnessAccount.Story.values().length,"the account tab has its progress, the five kinds and one advancement for every story: "+account.size());
        for(var holder:house)h.assertTrue(holder.value().parent().isPresent()==!holder.id().getPath().equals("house/letter"),"the journey tab has one root, the letter: "+holder.id());
        for(var holder:account)h.assertTrue(holder.value().parent().isPresent()==!holder.id().getPath().equals("account/account"),"the account tab has one root: "+holder.id());
        var all=new ArrayList<>(house);all.addAll(account);
        for(var holder:all){var display=holder.value().display().orElseThrow();
            h.assertTrue(!display.shouldAnnounceChat(),"no advancement announces to chat, so nobody learns from chat what another reader finished: "+holder.id());
            h.assertTrue(holder.value().rewards().experience()==0&&holder.value().rewards().loot().isEmpty()&&holder.value().rewards().recipes().isEmpty()&&holder.value().rewards().function().isEmpty(),"advancements record and never pay: "+holder.id());}
        for(var story:WitnessAccount.Story.values()){var holder=get(h,"account",story.id);
            h.assertTrue(holder!=null,"the story "+story.id+" has its advancement");
            h.assertTrue(holder.value().parent().orElseThrow().getPath().equals("account/kind_"+story.kind),"the story "+story.id+" sits under its kind");
            h.assertTrue(holder.value().display().orElseThrow().isHidden(),"the story "+story.id+" is hidden until it is heard to the end");}
        for(var kind:List.of("survival","understanding","memory","connection","release"))h.assertTrue(get(h,"account","kind_"+kind).value().display().orElseThrow().isHidden(),"the kind "+kind+" is hidden until earned");
        for(var ending:List.of("ending_witness","ending_wound","ending_locked"))h.assertTrue(get(h,"house",ending).value().display().orElseThrow().isHidden(),"every ending is hidden: "+ending);
        h.succeed();
    }

    @GameTest(template="empty") public static void aStoryAwardsItselfItsKindAndTheProgressOnlyForItsOwnReader(GameTestHelper h){
        var server=h.getLevel().getServer();var previous=LabyrinthData.get(server);var data=new LabyrinthData();server.overworld().getDataStorage().set("the_oldest_house_labyrinth",data);
        try{
            ServerPlayer reader=h.makeMockServerPlayerInLevel(),peer=h.makeMockServerPlayerInLevel();reader.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);peer.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);
            HouseAdvancements.sync(reader);HouseAdvancements.sync(peer);
            h.assertTrue(!HouseAdvancements.has(reader,"account","account")&&!HouseAdvancements.has(reader,"account","first_story"),"nothing of the account before a story ends");
            WitnessAccount.resolve(data,reader.getUUID(),WitnessAccount.Story.FLOORBOARDS,"took_up_the_board");HouseAdvancements.sync(reader);HouseAdvancements.sync(peer);
            h.assertTrue(HouseAdvancements.has(reader,"account","floorboards")&&HouseAdvancements.has(reader,"account","kind_understanding")&&HouseAdvancements.has(reader,"account","first_story")&&HouseAdvancements.has(reader,"account","account"),"the story, its kind, the first ending and the account itself");
            h.assertTrue(!HouseAdvancements.has(reader,"account","two_kinds")&&!HouseAdvancements.has(reader,"account","kind_survival"),"one kind is not two");
            h.assertTrue(!HouseAdvancements.has(peer,"account","floorboards")&&!HouseAdvancements.has(peer,"account","first_story"),"another reader's story is not the peer's");
            WitnessAccount.resolve(data,reader.getUUID(),WitnessAccount.Story.CLAP,"won");
            for(var story:List.of(WitnessAccount.Story.HARRIGAN,WitnessAccount.Story.MODEL_HOME,WitnessAccount.Story.DROWNED_TOWN))WitnessAccount.resolve(data,reader.getUUID(),story,"resolved");
            HouseAdvancements.sync(reader);
            h.assertTrue(HouseAdvancements.has(reader,"account","two_kinds")&&HouseAdvancements.has(reader,"account","kind_survival")&&HouseAdvancements.has(reader,"account","kind_connection")&&HouseAdvancements.has(reader,"account","five_stories"),"a second kind and five rooms");
            h.assertTrue(!HouseAdvancements.has(reader,"account","twenty_stories")&&!HouseAdvancements.has(reader,"account","enough")&&!HouseAdvancements.has(reader,"account","every_story"),"twenty, the quota and every room are still ahead");
            for(var story:WitnessAccount.Story.values())if(WitnessAccount.count(data,reader.getUUID())<WitnessAccount.REQUIRED)WitnessAccount.resolve(data,reader.getUUID(),story,"resolved");
            HouseAdvancements.sync(reader);
            h.assertTrue(HouseAdvancements.has(reader,"account","twenty_stories")&&HouseAdvancements.has(reader,"account","enough")==WitnessAccount.ready(data,reader.getUUID())&&!HouseAdvancements.has(reader,"account","every_story"),"the quota is the Witness's own, derived from the pool");
            for(var story:WitnessAccount.Story.values())WitnessAccount.resolve(data,reader.getUUID(),story,"resolved");HouseAdvancements.sync(reader);
            h.assertTrue(HouseAdvancements.has(reader,"account","every_story"),"every room");
            for(var story:WitnessAccount.Story.values())h.assertTrue(HouseAdvancements.has(reader,"account",story.id),"every story's own advancement: "+story.id);
        }finally{server.overworld().getDataStorage().set("the_oldest_house_labyrinth",previous);}
        h.succeed();
    }

    @GameTest(template="empty") public static void aSavedHistoryIsAwardedOnceAtLoginAndTheQuietRoomsAwardNothing(GameTestHelper h){
        var server=h.getLevel().getServer();var previous=LabyrinthData.get(server);var data=new LabyrinthData();server.overworld().getDataStorage().set("the_oldest_house_labyrinth",data);
        try{
            ServerPlayer reader=h.makeMockServerPlayerInLevel();reader.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);
            // A reader who has only been through the quiet rooms and been read by the House has nothing in the menu for it.
            var rooms=data.stateEntry(HouseReadSites.STATE,reader.getStringUUID());
            for(var room:HouseReadSites.Room.values()){var own=rooms.getCompound(room.key());own.putBoolean("Entered",true);rooms.put(room.key(),own);}
            data.setStateEntry(HouseReadSites.STATE,reader.getStringUUID(),rooms);
            HouseAdvancements.sync(reader);
            for(var holder:tab(h,"account"))h.assertTrue(!reader.getAdvancements().getOrStartProgress(holder).isDone(),"no quiet room and no read awards an account advancement: "+holder.id());
            // A save from before the menu: its stories are awarded the first time the reader is synced, and only once.
            WitnessAccount.resolve(data,reader.getUUID(),WitnessAccount.Story.GOATMAN,"kept_door_closed");WitnessAccount.resolve(data,reader.getUUID(),WitnessAccount.Story.SEANCE,"heard_the_medium");
            HouseAdvancements.sync(reader);
            h.assertTrue(HouseAdvancements.has(reader,"account","goatman")&&HouseAdvancements.has(reader,"account","seance")&&HouseAdvancements.has(reader,"account","two_kinds"),"the saved history is in the menu");
            var goatman=get(h,"account","goatman");var obtained=reader.getAdvancements().getOrStartProgress(goatman).getFirstProgressDate();
            HouseAdvancements.sync(reader);
            h.assertTrue(Objects.equals(obtained,reader.getAdvancements().getOrStartProgress(goatman).getFirstProgressDate()),"syncing again awards nothing twice");
        }finally{server.overworld().getDataStorage().set("the_oldest_house_labyrinth",previous);}
        h.succeed();
    }
}
